"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Menu as BaseMenu } from "@base-ui/react/menu";
import { Menubar as BaseMenubar } from "@base-ui/react/menubar";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/registry/default/button/button";
import {
  DropdownMenuCheckboxItem,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuLinkItem,
  DropdownMenuPortal,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
} from "@/registry/default/dropdown-menu/dropdown-menu";
import {
  solidSurface,
  type SurfaceLevel,
} from "@/registry/default/lib/elevated";
import "./menubar.css";

// A shell, as in Button Group and Toolbar. Triggers fill it with a 2px
// transparent-border inset (even at fractional display scales), and a
// highlight glides to the hovered, focused, or open trigger (menubar.css), so
// moving across open menus slides it from File to Edit.
const menubarVariants = cva(
  [
    "relative isolate flex w-fit items-stretch rounded-(--menubar-radius) data-[orientation=vertical]:flex-col",
    "[--menubar-item-radius:max(0px,calc(var(--menubar-radius)-var(--menubar-border,0px)-2px))]",
    // Label-color tints: hover 10%, press 14%
    "[--menubar-highlight:color-mix(in_oklab,currentColor_10%,transparent)] [--menubar-press:color-mix(in_oklab,currentColor_14%,transparent)]",
    "data-[orientation=horizontal]:h-(--menubar-h) data-[orientation=vertical]:min-w-(--menubar-h)",
    "data-disabled:opacity-60",
  ],
  {
    variants: {
      variant: {
        elevated: cn(solidSurface(2, 2), "text-foreground"),
        // Outline's border sits outside the fill, as on an outline Button.
        outline:
          "border-border bg-card text-foreground border bg-clip-padding [--menubar-border:1px]",
        soft: "bg-secondary text-secondary-foreground",
        ghost: "text-foreground",
      },
      // Button's height ladder (one step taller below sm); corners step with it.
      size: {
        sm: "[--menubar-h:--spacing(9)] sm:[--menubar-h:--spacing(8)] [--menubar-radius:calc(var(--radius)-2px)]",
        default:
          "[--menubar-h:--spacing(10)] sm:[--menubar-h:--spacing(9)] [--menubar-radius:var(--radius)]",
        lg: "[--menubar-h:--spacing(11)] sm:[--menubar-h:--spacing(10)] [--menubar-radius:calc(var(--radius)+2px)]",
      },
    },
    defaultVariants: {
      variant: "elevated",
      size: "default",
    },
  },
);

export type MenubarProps = BaseMenubar.Props &
  VariantProps<typeof menubarVariants> & {
    /** Glide a shared highlight between triggers. */
    highlight?: boolean;
  };

function Menubar({
  className,
  variant,
  size,
  highlight = true,
  children,
  ...props
}: MenubarProps) {
  return (
    <BaseMenubar
      data-slot="menubar"
      data-variant={variant ?? "elevated"}
      data-size={size ?? "default"}
      data-glide={highlight ? "" : undefined}
      className={cn(menubarVariants({ variant, size }), className)}
      {...props}
    >
      {children}
      {/* Last, so first-child selectors still match the first trigger. */}
      {highlight && <span aria-hidden data-slot="menubar-highlight" />}
    </BaseMenubar>
  );
}

function MenubarMenu(props: BaseMenu.Root.Props) {
  return <BaseMenu.Root data-slot="menubar-menu" {...props} />;
}

// A quiet Button: hover and the open menu paint the label tint. Menu triggers
// skip Button's press, as everywhere else.
const triggerClasses = cn(
  buttonVariants({ variant: "ghost", size: null }),
  "shrink-0 border-2 border-transparent px-2.5 text-sm font-medium text-current hover:text-current data-popup-open:text-current",
  "[--btn-bg-hover:var(--menubar-highlight)] [--btn-bg-active:var(--menubar-press)]",
  // Box corners are the paint's + 2px, so paint, gap, and focus ring (at
  // offset 0) are concentric.
  "rounded-[calc(var(--menubar-item-radius)+2px)] before:rounded-(--menubar-item-radius) focus-visible:outline-offset-0 focus-visible:z-10",
  "h-auto self-stretch in-data-[orientation=vertical]:h-[calc(var(--menubar-h)-var(--menubar-border,0px)*2)] in-data-[orientation=vertical]:justify-start",
);

function MenubarTrigger({
  className,
  delay = 0,
  closeDelay = 0,
  ...props
}: BaseMenu.Trigger.Props) {
  return (
    <BaseMenu.Trigger
      data-slot="menubar-trigger"
      data-menubar-item=""
      delay={delay}
      closeDelay={closeDelay}
      className={cn(triggerClasses, className)}
      {...props}
    />
  );
}

function MenubarContent({
  className,
  children,
  align = "start",
  alignOffset = 0,
  sideOffset = 4,
  level = 3,
  shadowLevel = 3,
  ...props
}: React.ComponentProps<typeof BaseMenu.Popup> & {
  align?: BaseMenu.Positioner.Props["align"];
  alignOffset?: BaseMenu.Positioner.Props["alignOffset"];
  sideOffset?: BaseMenu.Positioner.Props["sideOffset"];
  /** Surface elevation level for the popup bg (1-8). Bump when nesting inside a Dialog or other elevated container. Defaults to 3. */
  level?: SurfaceLevel;
  /** Shadow weight (1-8). Pinned to 3 by default so the menu reads the same regardless of nesting depth. */
  shadowLevel?: SurfaceLevel;
}) {
  return (
    <BaseMenu.Portal>
      {/* No guard here, unlike DropdownMenu: there one positioner is shared by
          detached triggers and physically travels between them. Each MenubarMenu
          mounts its own, with no previous position to animate from. */}
      <BaseMenu.Positioner
        className="z-50 h-(--positioner-height) max-h-(--available-height) w-(--positioner-width) max-w-(--available-width) transition-[top,left,right,bottom,transform] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none"
        align={align}
        alignOffset={alignOffset}
        sideOffset={sideOffset}
      >
        <BaseMenu.Popup
          data-slot="menubar-content"
          data-level={level}
          className={cn(
            "text-popover-foreground relative max-h-(--available-height) max-w-(--available-width) min-w-[12rem] overflow-hidden rounded-xl outline-none",
            solidSurface(level, shadowLevel),
            "h-(--popup-height,auto) w-(--popup-width,auto)",
            "origin-(--transform-origin) transition-[width,height,scale,opacity] duration-[150ms,150ms,100ms,100ms] ease-[cubic-bezier(0.22,1,0.36,1),cubic-bezier(0.22,1,0.36,1),var(--ease-out-expo),var(--ease-out-expo)]",
            "data-starting-style:scale-95 data-starting-style:opacity-0",
            "data-ending-style:scale-95 data-ending-style:opacity-0",
            // Own compositor layer while mounted. width/height in the transition
            // list stops Chrome compositing the scale, so rows re-raster every
            // frame and the differential stretch reads as a ripple. ContextMenu
            // escapes it by transitioning scale and opacity alone.
            "will-change-transform",
            "motion-reduce:transition-none motion-reduce:will-change-auto",
            // 'group' marks a switch to another menu in the bar, File to Edit.
            // Those swap instantly, as in native menu bars; only the first
            // open and the final close animate. 'dismiss' must animate or
            // there is no exit.
            // The start and end styles are pinned too, or the swap frame shows
            // both popups at opacity 0.
            "data-[instant=group]:transition-none data-[instant=group]:data-ending-style:scale-100 data-[instant=group]:data-ending-style:opacity-100 data-[instant=group]:data-starting-style:scale-100 data-[instant=group]:data-starting-style:opacity-100",
            className,
          )}
          {...props}
        >
          {/*
            Kept for sizing, not for content transitions. Base UI runs the popup
            auto-resize from inside the Viewport, and that is what writes
            --positioner-width / --positioner-height (plus --popup-width /
            --popup-height, which sit at `auto` between resizes). The positioner
            above sizes off those, so dropping the Viewport leaves them unset
            and its explicit box collapses.

            Deliberately carries no morph styling. A menubar can't morph: each
            MenubarMenu is its own Menu.Root, so moving from File to Edit mounts
            a new popup rather than swapping content within one, and
            data-current / data-previous / data-activation-direction never
            appear. (Verified: two distinct popup elements across a switch.)
          */}
          <BaseMenu.Viewport
            data-slot="menubar-viewport"
            // No `max-w`: `w-full` resolves against the popup's already-capped
            // content box, so the width bound is inherited for free.
            className="relative max-h-(--available-height) w-full overflow-clip overflow-y-auto p-1"
          >
            {children}
          </BaseMenu.Viewport>
        </BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  );
}

// The menu's contents are Dropdown Menu's parts: a menubar menu is the same
// Base UI Menu.
const MenubarPortal = DropdownMenuPortal;
const MenubarGroup = DropdownMenuGroup;
const MenubarLabel = DropdownMenuLabel;
const MenubarGroupLabel = DropdownMenuGroupLabel;
const MenubarItem = DropdownMenuItem;
const MenubarLinkItem = DropdownMenuLinkItem;
const MenubarCheckboxItem = DropdownMenuCheckboxItem;
const MenubarRadioGroup = DropdownMenuRadioGroup;
const MenubarRadioItem = DropdownMenuRadioItem;
const MenubarSeparator = DropdownMenuSeparator;
const MenubarShortcut = DropdownMenuShortcut;
const MenubarSub = DropdownMenuSub;
const MenubarSubTrigger = DropdownMenuSubTrigger;
const MenubarSubContent = DropdownMenuSubContent;

export {
  Menubar,
  MenubarPortal,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarGroup,
  MenubarSeparator,
  MenubarGroupLabel,
  MenubarLabel,
  MenubarItem,
  MenubarLinkItem,
  MenubarShortcut,
  MenubarCheckboxItem,
  MenubarRadioGroup,
  MenubarRadioItem,
  MenubarSub,
  MenubarSubTrigger,
  MenubarSubContent,
  menubarVariants,
};

/* -------------------------------------------------------------------------------------------------
 * Gliding highlight, in CSS anchor positioning, as in Button Group and Toolbar.
 *
 * The lit trigger (hover, focus, open menu) takes the anchor name and the
 * shared pill follows it. Without anchor positioning and anchor-scope, each
 * trigger paints its own hover instead.
 * -------------------------------------------------------------------------------------------------*/

[data-slot="menubar-highlight"] {
  display: none;
}

/* All anchor features or none: a partial implementation leaves the pill
 * unplaced or tied to another menubar. */
@supports (anchor-name: --menubar-item) and (anchor-scope: --menubar-item) and
  (inset: anchor(inside)) {
  [data-slot="menubar"][data-glide] {
    anchor-scope: --menubar-item;
  }

  /* The pill stands in for the triggers' own hover. */
  [data-slot="menubar"][data-glide] [data-menubar-item] {
    --btn-bg-hover: transparent;
    --btn-bg-active: transparent;
  }

  /* Focus, press, and the open menu's trigger hold the pill. Hover is gated
   * to real hover (:active covers taps). */
  [data-slot="menubar"][data-glide]
    [data-menubar-item]:not(:disabled, [data-disabled]):is(
      :focus-visible,
      :active,
      [data-popup-open]
    ) {
    anchor-name: --menubar-item;
  }

  /* While a menu is open, hovering another trigger opens it, so the pill
   * moves on hover rather than waiting for that menu to mount. The open
   * trigger lets go meanwhile, or two triggers would share the anchor. */
  @media (hover: hover) {
    [data-slot="menubar"][data-glide]:not(:has([data-menubar-item]:active))
      [data-menubar-item]:not(:disabled, [data-disabled]):hover {
      anchor-name: --menubar-item;
    }

    [data-slot="menubar"][data-glide]:has(
        [data-menubar-item]:not(:disabled, [data-disabled]):hover
      )
      [data-menubar-item][data-popup-open]:not(:hover, :focus-visible) {
      anchor-name: none;
    }
  }

  /* Leaving the menubar, the last trigger holds the anchor while the pill fades,
   * so it fades in place instead of collapsing. Button's own transitions
   * are restated so they survive. */
  [data-slot="menubar"][data-glide]:not(
      :has(
        [data-menubar-item]:not(:disabled, [data-disabled]):is(
            :hover,
            :focus-visible,
            :active,
            [data-popup-open]
          )
      )
    )
    [data-menubar-item] {
    transition:
      outline-width 100ms ease-out,
      outline-offset 100ms ease-out,
      outline-color 100ms ease-out,
      opacity 100ms ease-out,
      color 100ms ease-out,
      anchor-name 0s 80ms allow-discrete;
  }

  [data-slot="menubar"][data-glide] > [data-slot="menubar-highlight"] {
    display: block;
    position: absolute;
    position-anchor: --menubar-item;
    inset: anchor(inside);
    /* The anchor is the item's border box; the same 2px border lines the
     * fill up with the item's paint. */
    border: 2px solid transparent;
    border-radius: calc(var(--menubar-item-radius) + 2px);
    background: var(--menubar-highlight) padding-box;
    /* Rendered last, so it sits under the triggers inside the isolated menubar. */
    z-index: -1;
    pointer-events: none;
    opacity: 0;
    scale: 0.96;
    /* Entering from no anchor can't interpolate, so the pill appears in
     * place and only fades and grows. */
    transition:
      inset 80ms var(--ease-out-expo, cubic-bezier(0.19, 1, 0.22, 1)),
      opacity 80ms ease-out,
      scale 80ms ease-out,
      background-color 80ms ease-out;
  }

  [data-slot="menubar"][data-glide]:has(
      [data-menubar-item]:not(:disabled, [data-disabled]):is(
          :focus-visible,
          :active,
          [data-popup-open]
        )
    )
    > [data-slot="menubar-highlight"] {
    opacity: 1;
    scale: 1;
  }

  @media (hover: hover) {
    [data-slot="menubar"][data-glide]:has(
        [data-menubar-item]:not(:disabled, [data-disabled]):hover
      )
      > [data-slot="menubar-highlight"] {
      opacity: 1;
      scale: 1;
    }
  }

  /* Press, as on Button. Menu triggers skip it. */
  [data-slot="menubar"][data-glide]:has(
      [data-menubar-item]:active:not([aria-haspopup], :disabled)
    )
    > [data-slot="menubar-highlight"] {
    scale: var(--menubar-press-scale, 0.98);
    background-color: var(--menubar-press);
  }

  /* While a menu is open, moving across the bar opens the next one, and that
   * mount blocks the main thread for a few frames. The inset transition runs
   * there too, so it would stutter; the pill jumps with the menu instead. */
  [data-slot="menubar"][data-glide]:has([data-menubar-item][data-popup-open])
    > [data-slot="menubar-highlight"] {
    transition-property: opacity, scale, background-color;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="menubar"][data-glide] {
      --menubar-press-scale: 1;
    }

    [data-slot="menubar"][data-glide] > [data-slot="menubar-highlight"] {
      scale: 1;
      transition:
        opacity 80ms ease-out,
        background-color 80ms ease-out;
    }
  }
}
